{"path": "/app/shipclient/retry.py", "content": """"Retry policy for outbound HTTP calls made through shipclient."""

import re
from datetime import datetime, timezone

# Defaults from the HTTP client standard (v3) and the rate limit rules.
_DEFAULT_ATTEMPTS = 5
_DEFAULT_CAP = 8.0
_DEFAULT_MAX_RETRY_AFTER = 30.0
_FIRST_DELAY = 0.25

_RETRYABLE_STATUSES = frozenset({429, 502, 503, 504})
_RETRY_AFTER_STATUSES = frozenset({429, 503})
_IDEMPOTENT_METHODS = frozenset({"GET", "HEAD", "OPTIONS", "PUT", "DELETE"})

# Current retry profiles: service -> (attempts, backoff cap, max Retry-After).
_PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_MONTHS = {
    name: i + 1
    for i, name in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
         "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    )
}
_HTTP_DATE = re.compile(
    r"(Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) "
    r"(\d{2}):(\d{2}):(\d{2}) GMT"
)
_INTEGER = re.compile(r"[0-9]+")


def _header(headers: dict[str, str] | None, name: str) -> str | None:
    name = name.lower()
    for key, value in (headers or {}).items():
        if isinstance(key, str) and key.lower() == name:
            return value
    return None


def _retry_after_seconds(value: str | None, now: datetime) -> float | None:
    """Parsed Retry-After wait in seconds, or None if absent or malformed."""
    if value is None or not isinstance(value, str):
        return None
    value = value.strip(" \t")
    if _INTEGER.fullmatch(value):
        return float(int(value))
    m = _HTTP_DATE.fullmatch(value)
    if not m:
        return None
    month = _MONTHS.get(m.group(3))
    if month is None:
        return None
    try:
        when = datetime(
            int(m.group(4)), month, int(m.group(2)),
            int(m.group(5)), int(m.group(6)), int(m.group(7)),
            tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    # Retry profile for the called service, if a current one exists.
    attempts, cap, max_retry_after = (
        _DEFAULT_ATTEMPTS, _DEFAULT_CAP, _DEFAULT_MAX_RETRY_AFTER
    )
    service = _header(request_headers, "X-Service")
    if service is not None:
        profile = _PROFILES.get(service.lower())
        if profile is not None:
            attempts, cap, max_retry_after = profile

    # Which failures are retried.
    if status is not None and status not in _RETRYABLE_STATUSES:
        return None

    # Which requests are retried.
    verb = method.upper()
    if verb not in _IDEMPOTENT_METHODS:
        if verb not in ("POST", "PATCH"):
            return None
        key = _header(request_headers, "Idempotency-Key")
        if not isinstance(key, str) or not key.strip():
            return None

    # How many attempts.
    if attempt >= attempts:
        return None

    # Exponential backoff.
    delay = min(cap, _FIRST_DELAY * (2 ** min(max(attempt - 1, 0), 60)))

    # Retry-After.
    if status in _RETRY_AFTER_STATUSES:
        wait = _retry_after_seconds(_header(response_headers, "Retry-After"), now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(wait, delay)

    return float(delay)
